-- ═══════════════════════════════════════════════════════════════════════════
-- Constraints Prisma's schema language cannot express.
--
-- Prisma has no syntax for a partial index, and a plain `@@unique` is not a
-- substitute for any of the four cases below.
-- ═══════════════════════════════════════════════════════════════════════════

-- One account per email address per tenant, among live rows only.
--
-- Two things make this partial. First, `tenant_id` is in the key: two pharma
-- companies may legitimately both sell to the same pharmacy, and that pharmacy
-- may hold an account with each. Second, `deleted_at IS NULL` is in the
-- predicate: a soft-deleted account must not block the address from being
-- re-registered, which is what a plain unique index would do.
CREATE UNIQUE INDEX "user_tenant_email_active_key"
  ON "user" ("tenant_id", "email")
  WHERE "deleted_at" IS NULL AND "email" IS NOT NULL;

-- The same rule for phone numbers, which are an alternative sign-in identifier.
CREATE UNIQUE INDEX "user_tenant_phone_active_key"
  ON "user" ("tenant_id", "phone")
  WHERE "deleted_at" IS NULL AND "phone" IS NOT NULL;

-- Role codes are unique per tenant — and separately unique for the seeded
-- global roles, whose `tenant_id` is NULL.
--
-- A plain `@@unique([tenantId, code])` does not achieve this: Postgres treats
-- NULLs as distinct, so it would permit unlimited rows with `tenant_id = NULL`
-- and the same code. Two partial indexes express the intended rule exactly.
CREATE UNIQUE INDEX "role_tenant_code_key"
  ON "role" ("tenant_id", "code")
  WHERE "tenant_id" IS NOT NULL;

CREATE UNIQUE INDEX "role_global_code_key"
  ON "role" ("code")
  WHERE "tenant_id" IS NULL;

-- Feature flags follow the same pattern: a tenant may override a platform
-- default, but may not define the same key twice.
CREATE UNIQUE INDEX "feature_flag_tenant_key"
  ON "feature_flag" ("key", "tenant_id")
  WHERE "tenant_id" IS NOT NULL;

CREATE UNIQUE INDEX "feature_flag_global_key"
  ON "feature_flag" ("key")
  WHERE "tenant_id" IS NULL;

-- ═══════════════════════════════════════════════════════════════════════════
-- Make the audit log append-only at the database level.
--
-- The application has no update or delete path for this table, but a rule that
-- lives only in application code is a rule that a future migration, a support
-- script or a `psql` session can break without anyone noticing. An audit trail
-- that can be rewritten is not evidence, so the restriction is enforced where it
-- cannot be bypassed.
--
-- Mechanism: TRIGGERS, not GRANTs.
--
-- A `REVOKE UPDATE, DELETE ON audit_log FROM <role>` is the obvious approach and
-- it does not work. PostgreSQL gives a table's owner an implicit grant that
-- cannot be revoked — so if the application connects as the owner (the common
-- case, and what DATABASE_URL in .env.example implies), the revoke succeeds,
-- prints nothing alarming, and protects nothing. Worse, a migration that runs as
-- a *separate* migration role would revoke from itself rather than from the
-- application role, so it would also protect nothing while looking correct.
--
-- A BEFORE UPDATE/DELETE trigger that raises is owned by the migration role and
-- fires regardless of who holds the table privilege. The owner can still drop
-- the trigger, but that is a deliberate DDL act recorded in the schema, whereas
-- a missing grant is invisible.
--
-- TRUNCATE needs its own statement-level trigger: a row-level trigger never sees
-- it. Both are covered.
--
-- Escape hatch: retention purges and test fixtures set
--   SET LOCAL medichain.allow_audit_mutation = 'on';
-- for the duration of one transaction. Deliberate, greppable, and scoped to a
-- transaction rather than a session, so it cannot leak into request handling.
-- ═══════════════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION "audit_log_reject_mutation"()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  -- `true` as the second argument to current_setting means "return NULL if
  -- unset" instead of raising. An unset GUC is the normal case.
  IF current_setting('medichain.allow_audit_mutation', true) = 'on' THEN
    -- NEW is NULL on DELETE, OLD is NULL on UPDATE; COALESCE picks whichever
    -- exists so the row is passed through unchanged.
    RETURN COALESCE(NEW, OLD);
  END IF;

  RAISE EXCEPTION
    'audit_log is append-only: % is not permitted', TG_OP
    USING
      ERRCODE = 'restrict_violation',
      HINT = 'An audit trail that can be rewritten is not evidence. If this is a retention purge or a test fixture, wrap it in a transaction that sets: SET LOCAL medichain.allow_audit_mutation = ''on'';';
END;
$$;

CREATE TRIGGER "audit_log_no_row_mutation"
  BEFORE UPDATE OR DELETE ON "audit_log"
  FOR EACH ROW
  EXECUTE FUNCTION "audit_log_reject_mutation"();

CREATE TRIGGER "audit_log_no_truncate"
  BEFORE TRUNCATE ON "audit_log"
  FOR EACH STATEMENT
  EXECUTE FUNCTION "audit_log_reject_mutation"();

-- Defence in depth for the multi-role setup: if a future migration ever grants
-- table privileges to PUBLIC, this closes it. It is not the primary mechanism —
-- see the comment above for why a grant-based approach cannot be relied on.
REVOKE UPDATE, DELETE, TRUNCATE ON "audit_log" FROM PUBLIC;

-- Report the state honestly rather than claiming protection that may not apply.
DO $$
DECLARE
  owner_role text;
BEGIN
  SELECT pg_catalog.pg_get_userbyid(c.relowner) INTO owner_role
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE c.relname = 'audit_log' AND n.nspname = current_schema();

  IF owner_role = current_user THEN
    RAISE NOTICE
      'audit_log is append-only via triggers. NOTE: the current role (%) owns the table, so it can drop the trigger. For defence in depth in production, run migrations as a separate owner role and grant the application role only INSERT, SELECT on audit_log.',
      current_user;
  ELSE
    RAISE NOTICE
      'audit_log is append-only via triggers for role % (table owner: %).', current_user, owner_role;
  END IF;
EXCEPTION
  WHEN insufficient_privilege THEN
    RAISE NOTICE
      'audit_log triggers created, but the REVOKE was skipped: insufficient privilege.';
END $$;
